NEW: Allows WF1 (or any workflow) to call this workflow programmatically.
Accepts: { exam_code, scraped_dir, clear_first }
If not provided, Configure Index Job uses safe defaults.

parameters.jsCode:
// Works for BOTH triggers:
//   Manual Trigger      → $input.first().json = {}
//   Execute Workflow    → $input.first().json = { exam_code, scraped_dir, clear_first }
// Defaults ensure safe standalone manual execution.
const input = $input.first().json;
return [{
  json: {
    exam_code:   input.exam_code   || 'all',
    scraped_dir: input.scraped_dir || './data/scraped',
    clear_first: input.clear_first !== undefined ? input.clear_first : false
  }
}];

const data = $input.first().json;
const results = data.results || {};
const summary = Object.entries(results).map(([exam, r]) => ({
  exam,
  status: r.status,
  chunks: r.chunks_indexed || 0,
  files: r.files || 0,
  note: r.reason || ''
}));
const total = summary.reduce((s, r) => s + r.chunks, 0);
console.log('Total chunks indexed: ' + total);
console.log(JSON.stringify(summary, null, 2));
return [{ json: { summary, total_chunks: total } }];
